// Daily line surf. There is no freehand stroke: each beat adds one segment,
// and curvature or a cut is what changes speed (2026-10-21). A lip asks for
// speed. A wall, or a curve off the side, ends the ride. The course is
// generated by walking one legal line and never storing that line.

import { mulberry32 } from "./daily";

export const GAME_ID = "line-surf";
export const STEPS = 8;
export const LANES = 3;
export const LIP_SPEED = 2;
export const MAX_SPEED = 4;
export const ACTS = ["straight", "left", "right", "cut"] as const;

export type Act = (typeof ACTS)[number];
export type Tile = "open" | "wall" | "lip";
export type Phase = "ready" | "play" | "won" | "lost";

export interface Puzzle {
  seed: number;
  columns: Tile[][];
}

export interface Run {
  puzzle: Puzzle;
  phase: Phase;
  step: number;
  lane: number;
  speed: number;
}

interface Spot {
  lane: number;
  speed: number;
}

export function createPuzzle(seed: number): Puzzle {
  const mixed = seed >>> 0;
  const rng = mulberry32(mixed ^ 0x51a70001);
  let spot: Spot = { lane: 1, speed: 2 };
  const columns: Tile[][] = [];
  for (let step = 0; step < STEPS; step += 1) {
    const tiles: Tile[] = ["open", "open", "open"];
    const act = forcedAct(spot.lane, step, rng);
    const next = moved(spot, act);
    if (!next) {
      columns.push(tiles);
      continue;
    }
    if (act === "left" || act === "right") tiles[spot.lane] = "wall";
    if (next.speed >= LIP_SPEED && rng() < 0.5) tiles[next.lane] = "lip";
    const others = [0, 1, 2].filter((lane) => lane !== next.lane && tiles[lane] === "open");
    if (others.length > 0 && rng() < 0.75) {
      const lane = others[Math.floor(rng() * others.length)] ?? 0;
      tiles[lane] = "wall";
    }
    if (tiles[next.lane] === "wall" || (tiles[next.lane] === "lip" && next.speed < LIP_SPEED)) tiles[next.lane] = "open";
    columns.push(tiles);
    spot = next;
  }
  return { seed: mixed, columns };
}

export function createRun(puzzle: Puzzle): Run {
  return { puzzle, phase: "ready", step: 0, lane: 1, speed: 2 };
}

// The result button used to rebuild today's seed. A practice wave has to be a
// different board, or "again" is the same daily course (2026-10-21).
export function freshSeed(salt: number, dailySeed: number): number {
  const next = salt >>> 0;
  const daily = dailySeed >>> 0;
  return next === daily ? (next + 1) >>> 0 : next;
}

export function begin(run: Run): Run {
  if (run.phase !== "ready") return run;
  return { ...run, phase: "play" };
}

export function ride(run: Run, act: Act): Run {
  if (run.phase !== "play") return run;
  const next = moved(run, act);
  if (!next) return { ...run, phase: "lost" };
  const column = run.puzzle.columns[run.step];
  const tile = column?.[next.lane] ?? "wall";
  if (tile === "wall" || (tile === "lip" && next.speed < LIP_SPEED)) {
    return { ...run, lane: next.lane, speed: next.speed, phase: "lost" };
  }
  const step = run.step + 1;
  if (step >= STEPS) return { ...run, ...next, step, phase: "won" };
  return { ...run, ...next, step };
}

export function expire(run: Run): Run {
  if (run.phase !== "play") return run;
  return { ...run, phase: "lost" };
}

function forcedAct(lane: number, step: number, rng: () => number): Act {
  if (step % 3 === 2) {
    if (lane === 0) return "right";
    if (lane === 2) return "left";
    return rng() < 0.5 ? "left" : "right";
  }
  const choices: Act[] = ["straight"];
  if (lane > 0) choices.push("left");
  if (lane < LANES - 1) choices.push("right");
  return choices[Math.floor(rng() * choices.length)] ?? "straight";
}

function moved(spot: Spot, act: Act): Spot | null {
  if (act === "straight") return { lane: spot.lane, speed: Math.min(MAX_SPEED, spot.speed + 1) };
  if (act === "cut") return { lane: spot.lane, speed: 0 };
  if (act === "left") {
    if (spot.lane === 0) return null;
    return { lane: spot.lane - 1, speed: Math.max(0, spot.speed - 1) };
  }
  if (spot.lane === LANES - 1) return null;
  return { lane: spot.lane + 1, speed: Math.max(0, spot.speed - 1) };
}
